type Stats struct {
    mu    sync.Mutex
    count map[string]int
}

func (s Stats) Inc(key string) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.count[key]++
}

func fetchFirst(urls []string) string {
    ch := make(chan string)
    for _, u := range urls {
        go func(u string) {
            ch <- fetch(u)
        }(u)
    }
    return <-ch   // birinchi javob
}
